package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

// ensure decimal import is used
var _ = decimal.NewFromInt(0)

type PartRec struct { // 01 PART-REC, 15 bytes
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsLabel string   // PIC X(20) len=20 = SPACES
var WsACount int64   // PIC 99 len=2 = 0
var WsTotalA int64   // PIC 999 len=3 = 0
var WsCount int64    // PIC 999 len=3 = 0

// additional runtime state
var curRec PartRec
var records []string
var recPos int

func truncateInt64(v int64, digits int) int64 {
	if digits <= 0 {
		return 0
	}
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	// keep low-order digits, handle negative? not needed here
	if v < 0 {
		// COBOL keeps sign? For now just mod positive part and reapply sign
		neg := v < 0
		if neg {
			v = -v
		}
		v = v % mod
		if neg {
			v = -v
		}
		return v
	}
	return v % mod
}

func MainPara() {
	// OPEN INPUT PART-FILE
	WsEofFlag = "N"
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	WsTotalA = 0
	WsCount = 0

	f, err := os.Open("input.dat")
	if err != nil {
		// file not found => treat as empty
		records = nil
		recPos = 0
	} else {
		scanner := bufio.NewScanner(f)
		// allow long lines
		buf := make([]byte, 0, 64*1024)
		scanner.Buffer(buf, 1024*1024)
		var recs []string
		for scanner.Scan() {
			line := scanner.Text()
			// Remove trailing \r if present (LINE SEQUENTIAL may have CRLF)
			if strings.HasSuffix(line, "\r") {
				line = line[:len(line)-1]
			}
			// We store raw line; padding/truncation done on read
			recs = append(recs, line)
		}
		f.Close()
		records = recs
		recPos = 0
	}
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	// CLOSE PART-FILE (already closed)
	SummaryPara()
}

func ReadPara() {
	if recPos >= len(records) {
		WsEofFlag = "Y"
		return
	}
	line := records[recPos]
	recPos++

	// pad on right with spaces to record length 15, truncate if longer
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	// parse fields
	curRec.LbPart = line[0:8]
	curRec.LbRegion = line[8:11]
	serialStr := line[11:15]
	serialStrTrim := strings.TrimSpace(serialStr)
	if serialStrTrim == "" {
		curRec.LbSerial = 0
	} else {
		// serial should be digits; if contains spaces, remove?
		// keep only digits? but spec says digits only
		v, err := strconv.ParseInt(strings.TrimSpace(serialStr), 10, 64)
		if err != nil {
			// try to handle non-numeric by treating as 0
			// extract digits
			digits := ""
			for _, ch := range serialStr {
				if ch >= '0' && ch <= '9' {
					digits += string(ch)
				}
			}
			if digits == "" {
				v = 0
			} else {
				v, _ = strconv.ParseInt(digits, 10, 64)
			}
		}
		curRec.LbSerial = v
	}
}

func delimitedBySpace(s string) string {
	idx := strings.Index(s, " ")
	if idx >= 0 {
		return s[:idx]
	}
	return s
}

func ProcessPara() {
	// MOVE SPACES TO WS-LABEL
	WsLabel = strings.Repeat(" ", 20)
	// MOVE 0 TO WS-A-COUNT
	WsACount = 0
	WsACount = truncateInt64(WsACount, 2)

	// INSPECT LB-PART TALLYING WS-A-COUNT FOR ALL "A"
	// curRec.LbPart is X(8) exactly 8 chars
	cnt := strings.Count(curRec.LbPart, "A")
	WsACount = int64(cnt)
	WsACount = truncateInt64(WsACount, 2)

	// STRING LB-REGION DELIMITED BY SPACE
	//        "-" DELIMITED BY SIZE
	//        LB-PART DELIMITED BY SPACE
	//        "-" DELIMITED BY SIZE
	//        LB-SERIAL DELIMITED BY SIZE
	//     INTO WS-LABEL
	regionPart := delimitedBySpace(curRec.LbRegion)
	partPart := delimitedBySpace(curRec.LbPart)
	serialFormatted := fmt.Sprintf("%04d", curRec.LbSerial)
	// COBOL numeric DISPLAY: if more than 4 digits, low-order digits kept?
	// truncate high-order digits if needed
	if len(serialFormatted) > 4 {
		serialFormatted = serialFormatted[len(serialFormatted)-4:]
	}

	concat := regionPart + "-" + partPart + "-" + serialFormatted
	// STRING INTO WS-LABEL: left aligned, remainder stays spaces (already spaces)
	// if exceeds 20, truncate
	if len(concat) > 20 {
		concat = concat[:20]
	}
	// place into WsLabel (20)
	WsLabel = concat + strings.Repeat(" ", 20-len(concat))

	// INSPECT WS-LABEL REPLACING ALL "0" BY "O"
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")

	// ADD WS-A-COUNT TO WS-TOTAL-A
	WsTotalA = WsTotalA + WsACount
	WsTotalA = truncateInt64(WsTotalA, 3)

	// ADD 1 TO WS-COUNT
	WsCount = WsCount + 1
	WsCount = truncateInt64(WsCount, 3)

	// DISPLAY WS-LABEL " A=" WS-A-COUNT
	// WS-LABEL is X(20) exactly 20 chars, WS-A-COUNT is PIC 99 zero-padded width 2
	aCountStr := fmt.Sprintf("%02d", WsACount)
	// ensure width 2 truncate high order if needed (already truncated)
	if len(aCountStr) > 2 {
		aCountStr = aCountStr[len(aCountStr)-2:]
	}
	fmt.Fprint(os.Stdout, WsLabel+" A="+aCountStr+"\n")

	// PERFORM READ-PARA
	ReadPara()
}

func SummaryPara() {
	// DISPLAY "LABELS: " WS-COUNT " A-TOTAL: " WS-TOTAL-A.
	countStr := fmt.Sprintf("%03d", WsCount)
	if len(countStr) > 3 {
		countStr = countStr[len(countStr)-3:]
	}
	totalStr := fmt.Sprintf("%03d", WsTotalA)
	if len(totalStr) > 3 {
		totalStr = totalStr[len(totalStr)-3:]
	}
	fmt.Fprint(os.Stdout, "LABELS: "+countStr+" A-TOTAL: "+totalStr+"\n")
}

func main() {
	MainPara()
}
